// Класифікуємо опубліковані сутності OData і підсвічуємо ті, що потрібні для
// вигрузки товарів і залишків. Якщо потрібного тут немає — об'єкт не доданий
// у "Склад стандартного інтерфейсу OData" (див. 01-odata-setup.md, крок 1.1).
const raw = $input.first().json;
const list = raw.value || raw.EntitySets || [];
const names = list.map((v) => (typeof v === 'string' ? v : v.name || v.url)).filter(Boolean);

const kinds = {};
for (const n of names) {
  const kind = n.includes('_') ? n.split('_')[0] : 'other';
  kinds[kind] = (kinds[kind] || 0) + 1;
}

const KEYWORDS = [
  'номенклатур', 'номенклатура', 'характеристик', 'запас', 'товар', 'склад',
  'цін', 'цен', 'одиниц', 'единиц', 'штрихкод', 'резерв', 'замовлен', 'заказ',
  'упаковк', 'вид', 'групп', 'груп'
];
const interesting = names.filter((n) => {
  const low = n.toLowerCase();
  return KEYWORDS.some((k) => low.includes(k));
});

return [{
  json: {
    total: names.length,
    kinds,
    interestingCount: interesting.length,
    interesting,
    all: names
  }
}];

// Витягуємо склад полів по цікавих нам сутностях з XML-метаданих.
// Вивід цього вузла — те, що потрібно віддати для побудови таблиці мапінгу.
const xml = $input.first().json.data || $input.first().json.body || '';
const interesting = ($('Класифікація сутностей').first().json.interesting || []).map((s) => s.toLowerCase());

const out = [];
const entityRe = /<EntityType Name="([^"]+)"([\s\S]*?)<\/EntityType>/g;
let m;
while ((m = entityRe.exec(xml)) !== null) {
  const name = m[1];
  const low = name.toLowerCase();
  const wanted = interesting.length === 0 || interesting.some((i) => low.includes(i) || i.includes(low));
  if (!wanted) continue;
  const props = [...m[2].matchAll(/<Property Name="([^"]+)" Type="([^"]+)"/g)]
    .map((p) => `${p[1]}: ${p[2].replace('Edm.', '')}`);
  out.push({ entity: name, propertyCount: props.length, properties: props });
}

// Віртуальні таблиці регістрів (Balance / SliceLast) публікуються як FunctionImport
// або як окремі EntityType — фіксуємо, що реально доступно.
const functions = [...xml.matchAll(/<FunctionImport Name="([^"]+)"/g)].map((f) => f[1]);

return [{
  json: {
    metadataBytes: xml.length,
    entitiesFound: out.length,
    functionImports: functions,
    entities: out
  }
}];
